package au.monster.tracker;

import android.app.*;
import android.os.Bundle;
import android.content.Context;
import android.content.pm.PackageInfo;
import java.util.*;

/** Dependency-free device tests of the production Store, using isolated database files. */
public final class DatabaseTestRunner extends Instrumentation {
    private int total=32,index=0,passed=0,failed=0;
    interface Case {void run()throws Exception;}
    @Override public void onCreate(Bundle args){super.onCreate(args);start();}
    private void eq(Object a,Object b){if(!Objects.equals(a,b))throw new AssertionError("got="+a+", expected="+b);}
    private void check(boolean condition){if(!condition)throw new AssertionError("Condition failed");}
    private Ledger.Event sale(){long now=System.currentTimeMillis();return new Ledger.Event(Ledger.id(),now,now,"deal",2,"card",600,25,0,"device test",null);}
    private void test(String name,Case fn){index++;Bundle b=new Bundle();b.putString("class",getClass().getName());b.putString("test",name);b.putInt("numtests",total);b.putInt("current",index);sendStatus(1,b);try{fn.run();passed++;b.putString("stream","PASS "+name+"\n");sendStatus(0,b);}catch(Throwable e){failed++;b.putString("stream","FAIL "+name+": "+e+"\n");b.putString("stack",android.util.Log.getStackTraceString(e));sendStatus(-2,b);}}
    interface WithStore {void run(Store store,String filename)throws Exception;}
    private void fresh(WithStore fn)throws Exception{Context c=getTargetContext();String file="test-"+UUID.randomUUID()+".db";Store s=new Store(c,file);try{fn.run(s,file);}finally{s.close();c.deleteDatabase(file);}}
    @Override public void onStart(){
        test("firstLaunchOfflineOpeningExactlyOnce",()->fresh((s,file)->{eq(s.snapshot().totals().stock(),20L);eq(s.snapshot().totals().purchases(),5000L);eq(s.snapshot().totals().result(),-5000L);eq(s.snapshot().events().get(1).timestamp(),null);s.close();try(Store reopened=new Store(getTargetContext(),file)){eq(reopened.snapshot().events().size(),2);eq(reopened.snapshot().totals().stock(),20L);}}));
        test("cashCardDealsAndPersistentRestart",()->fresh((s,file)->{s.record(sale());eq(s.snapshot().totals().stock(),18L);eq(s.snapshot().totals().card(),600L);eq(s.snapshot().totals().fees(),25L);s.close();try(Store again=new Store(getTargetContext(),file)){eq(again.snapshot().events().size(),3);eq(again.snapshot().totals().result(),-4425L);}}));
        test("sameIdIsIdempotent",()->fresh((s,file)->{var e=sale();check(s.record(e));check(!s.record(e));eq(s.snapshot().events().size(),3);}));
        test("pendingSaveRecoveryBeforeAndAfterCommit",()->fresh((s,file)->{var e=sale();s.stage(e);s.close();try(Store afterCrash=new Store(getTargetContext(),file)){afterCrash.recoverPending();eq(afterCrash.snapshot().events().size(),3);}try(Store secondCrash=new Store(getTargetContext(),file)){secondCrash.recoverPending();eq(secondCrash.snapshot().events().size(),3);secondCrash.acknowledge(e.id());eq(secondCrash.recoverPending(),null);}}));
        test("undoAndStockLimits",()->fresh((s,file)->{var e=sale();s.record(e);s.record(Ledger.event("undo",0,"none",0,0,0,"Mistaken entry",System.currentTimeMillis(),e.id()));eq(s.snapshot().totals().stock(),20L);try{s.record(Ledger.event("missing",21,"none",0,0,0,"",System.currentTimeMillis(),null));throw new AssertionError("Oversale accepted");}catch(IllegalArgumentException expected){}eq(s.snapshot().events().size(),4);}));
        test("backupRestoreMergeAndSettings",()->fresh((s,file)->{s.record(sale());s.setPrices(new Ledger.Prices(400,700));var before=s.snapshot();var data=Backup.decode(Backup.encode(new Backup.Data(before.events(),before.prices())));String other="restore-"+UUID.randomUUID()+".db";try(Store replacement=new Store(getTargetContext(),other)){eq(replacement.importBackup(data),1);eq(replacement.importBackup(data),0);eq(replacement.snapshot().totals().stock(),18L);eq(replacement.snapshot().prices().single(),400L);}finally{getTargetContext().deleteDatabase(other);}}));
        test("conflictingRestoreIsTransactional",()->fresh((s,file)->{var e=sale();s.record(e);var es=new ArrayList<>(s.snapshot().events());es.set(2,new Ledger.Event(e.id(),e.timestamp(),e.recordedAt(),e.type(),e.quantity(),e.payment(),650,e.fee(),e.cost(),e.note(),e.target()));try{s.importBackup(new Backup.Data(es,new Ledger.Prices(999,999)));throw new AssertionError("Conflict accepted");}catch(IllegalArgumentException expected){}eq(s.snapshot().events().size(),3);eq(s.snapshot().prices().single(),350L);}));
        test("corruptBackupRejectedWithoutWrites",()->fresh((s,file)->{String text=Backup.encode(new Backup.Data(s.snapshot().events(),s.snapshot().prices()));try{s.importBackup(Backup.decode(text.substring(0,text.length()/2)));throw new AssertionError("Corrupt file accepted");}catch(IllegalArgumentException expected){}eq(s.snapshot().events().size(),2);}));
        test("cameraPermissionWithoutBroadStorage",()->{PackageInfo info=getTargetContext().getPackageManager().getPackageInfo(getTargetContext().getPackageName(),android.content.pm.PackageManager.GET_PERMISSIONS);if(info.requestedPermissions!=null)for(String p:info.requestedPermissions)check(!p.equals("android.permission.READ_EXTERNAL_STORAGE")&&!p.equals("android.permission.MANAGE_EXTERNAL_STORAGE"));check(getTargetContext().getAssets().open("schema.sql")!=null);});
        test("receiptPhotoSurvivesRestartAndBackupRestore",()->fresh((s,file)->{android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(8,8,android.graphics.Bitmap.Config.ARGB_8888);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();image.compress(android.graphics.Bitmap.CompressFormat.JPEG,90,bytes);image.recycle();var photo=Receipts.photo(Ledger.OPEN_PURCHASE,bytes.toByteArray());s.addReceipt(photo);s.close();try(Store reopened=new Store(getTargetContext(),file)){eq(reopened.snapshot().receipts().get(0),photo);var data=Backup.decode(Backup.encode(new Backup.Data(reopened.snapshot().events(),reopened.snapshot().prices(),reopened.snapshot().receipts())));String other="photo-restore-"+UUID.randomUUID()+".db";try(Store replacement=new Store(getTargetContext(),other)){replacement.importBackup(data);replacement.importBackup(data);eq(replacement.snapshot().receipts().size(),1);eq(replacement.snapshot().receipts().get(0),photo);}finally{getTargetContext().deleteDatabase(other);}}}));
        test("versionOneUpgradePreservesLedger",()->fresh((s,file)->{s.record(sale());s.close();try(var db=android.database.sqlite.SQLiteDatabase.openDatabase(getTargetContext().getDatabasePath(file).getPath(),null,0)){db.execSQL("DROP TRIGGER audit_photo_insert");db.execSQL("DROP TRIGGER audit_ledger_insert");for(String table:Ledger.list("finance_tax_plans","finance_tax","finance_settings","catalog_plans","event_products","flavour_transfers","barcodes","product_settings","products","document_cancellations","deliveries","purchase_lines","documents","supplier_receipts","audit","receipts","checkout"))db.execSQL("DROP TABLE "+table);db.setVersion(1);}try(Store upgraded=new Store(getTargetContext(),file)){eq(upgraded.snapshot().events().size(),3);eq(upgraded.snapshot().totals().stock(),18L);eq(upgraded.snapshot().receipts().size(),0);eq(upgraded.checkout(),null);}}));
        test("pendingStripePaymentSurvivesRestartAndBlocksSales",()->fresh((s,file)->{var e=sale();s.beginCheckout(e);s.close();try(Store reopened=new Store(getTargetContext(),file)){eq(reopened.checkout(),e);try{reopened.stage(sale());throw new AssertionError("Pending payment allowed another sale");}catch(IllegalStateException expected){}eq(reopened.snapshot().events().size(),2);reopened.finishCheckout(e);eq(reopened.checkout(),null);eq(reopened.snapshot().events().size(),3);}}));
        test("simulatedStripePaymentLeavesStockUntouched",()->fresh((s,file)->{var e=sale();s.beginCheckout(e);s.clearCheckout(e.id());eq(s.snapshot().totals().stock(),20L);eq(s.snapshot().events().size(),2);eq(s.checkout(),null);}));
        test("receiptImportConflictRollsBackPrices",()->fresh((s,file)->{android.graphics.Bitmap bitmap=android.graphics.Bitmap.createBitmap(8,8,android.graphics.Bitmap.Config.ARGB_8888);java.io.ByteArrayOutputStream output=new java.io.ByteArrayOutputStream();bitmap.compress(android.graphics.Bitmap.CompressFormat.JPEG,90,output);bitmap.recycle();byte[] image=output.toByteArray();var p=Receipts.photo(Ledger.OPEN_PURCHASE,image);s.addReceipt(p);var conflicting=new Receipts.Photo(p.id(),Ledger.OPEN_MISSING,p.createdAt(),p.mime(),p.base64(),p.sha256());try{s.importBackup(new Backup.Data(s.snapshot().events(),new Ledger.Prices(999,999),Ledger.list(conflicting)));throw new AssertionError("Receipt conflict accepted");}catch(IllegalArgumentException expected){}eq(s.snapshot().prices().single(),350L);eq(s.snapshot().receipts().get(0),p);}));
        test("mainActivityStartsOfflineWithStripeOptional",()->{android.app.Activity activity=startActivitySync(new android.content.Intent(getTargetContext(),MainActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1500);check(!activity.isFinishing());runOnMainSync(activity::finish);});
        test("migrateGenuineVersion1WithoutLosingRecords",()->{Context c=getTargetContext();String file="migration-"+UUID.randomUUID()+".db";android.database.sqlite.SQLiteDatabase old=c.openOrCreateDatabase(file,0,null);try{try(java.io.BufferedReader reader=new java.io.BufferedReader(new java.io.InputStreamReader(c.getAssets().open("schema-v1.sql")))){String line;StringBuilder statement=new StringBuilder();while((line=reader.readLine())!=null){statement.append(line).append('\n');if(line.trim().endsWith(";")){old.execSQL(statement.toString());statement.setLength(0);}}}for(var e:Ledger.opening(System.currentTimeMillis())){android.content.ContentValues v=new android.content.ContentValues();v.put("id",e.id());v.putNull("timestamp");v.put("recorded_at",e.recordedAt());v.put("type",e.type());v.put("quantity",e.quantity());v.put("payment",e.payment());v.put("revenue",e.revenue());v.put("fee",e.fee());v.put("cost",e.cost());v.put("note",e.note());old.insertOrThrow("events",null,v);}old.execSQL("INSERT INTO settings VALUES('single',350)");old.execSQL("INSERT INTO settings VALUES('deal',600)");old.setVersion(1);}finally{old.close();}try(Store migrated=new Store(c,file)){eq(migrated.snapshot().events().size(),2);eq(migrated.snapshot().events().get(1).timestamp(),null);eq(migrated.snapshot().totals().stock(),20L);eq(new BusinessStore(migrated).audit().size(),2);eq(migrated.database().getVersion(),5);}finally{c.deleteDatabase(file);}});
        test("purchaseDocumentWaitsForConfirmedPartialDelivery",()->fresh((s,file)->{var b=new BusinessStore(s);var line=new Purchases.Line(Ledger.id(),"Monster",1,24,5001,455,true);var doc=new Purchases.Document(Ledger.id(),"purchase","Supplier","INV1",null,System.currentTimeMillis(),5001,455,"","",null,Ledger.list(line));b.add(doc,null);eq(s.snapshot().totals().stock(),20L);String id=Ledger.id();long now=System.currentTimeMillis();b.receive(id,line.id(),12,now,"");b.receive(id,line.id(),12,now,"");eq(s.snapshot().totals().stock(),32L);eq(s.snapshot().totals().purchases(),7500L);b.receive(Ledger.id(),line.id(),12,now,"");eq(s.snapshot().totals().stock(),44L);eq(s.snapshot().totals().purchases(),10001L);}));
        test("duplicateReceiptRejectedWithoutInventoryChange",()->fresh((s,file)->{var b=new BusinessStore(s);var receipt=Purchases.receipt("%PDF-original".getBytes());var doc=new Purchases.Document(Ledger.id(),"expense","Supplier","INV1",null,System.currentTimeMillis(),500,0,"Travel","",receipt.hash(),Ledger.list());b.add(doc,receipt);try{b.add(new Purchases.Document(Ledger.id(),"expense","Supplier","INV2",null,System.currentTimeMillis(),500,0,"Travel","",receipt.hash(),Ledger.list()),receipt);throw new AssertionError("Duplicate receipt accepted");}catch(IllegalArgumentException expected){}eq(b.view().documents().size(),1);eq(s.snapshot().totals().stock(),20L);check(java.util.Arrays.equals(receipt.content(),b.original(receipt.hash()).content()));}));
        test("operatingExpenseUndoKeepsHistoryAndAudit",()->fresh((s,file)->{var b=new BusinessStore(s);var doc=new Purchases.Document(Ledger.id(),"expense","Supplier","",null,System.currentTimeMillis(),500,0,"Travel","",null,Ledger.list());b.add(doc,null);eq(b.view().expenses(),500L);b.cancel(Ledger.id(),doc.id(),"Mistake");eq(b.view().expenses(),0L);eq(b.view().documents().size(),1);eq(b.audit().size(),4);}));
        test("fullBackupRestoresOriginalReceiptsAndPurchases",()->fresh((s,file)->{var b=new BusinessStore(s);var receipt=Purchases.receipt("%PDF-original backup".getBytes());var doc=new Purchases.Document(Ledger.id(),"expense","Supplier","",null,System.currentTimeMillis(),500,0,"Travel","",receipt.hash(),Ledger.list());b.add(doc,receipt);var backup=Backup.decode(Backup.encode(s.fullBackup()));String other="full-restore-"+UUID.randomUUID()+".db";try(Store restored=new Store(getTargetContext(),other)){restored.importBackup(backup);restored.importBackup(backup);var result=new BusinessStore(restored);eq(result.view().documents().size(),1);eq(result.view().expenses(),500L);check(java.util.Arrays.equals(result.original(receipt.hash()).content(),receipt.content()));}finally{getTargetContext().deleteDatabase(other);}}));
        test("versionTwoUpgradeKeepsExistingPhotosAndPendingPayment",()->fresh((s,file)->{android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(8,8,android.graphics.Bitmap.Config.ARGB_8888);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();image.compress(android.graphics.Bitmap.CompressFormat.JPEG,90,bytes);image.recycle();var photo=Receipts.photo(Ledger.OPEN_PURCHASE,bytes.toByteArray());s.addReceipt(photo);var pending=sale();s.beginCheckout(pending);s.close();try(var db=android.database.sqlite.SQLiteDatabase.openDatabase(getTargetContext().getDatabasePath(file).getPath(),null,0)){db.execSQL("DROP TRIGGER audit_photo_insert");db.execSQL("DROP TRIGGER audit_ledger_insert");db.execSQL("DROP TRIGGER photos_no_update");db.execSQL("DROP TRIGGER photos_no_delete");for(String table:Ledger.list("finance_tax_plans","finance_tax","finance_settings","catalog_plans","event_products","flavour_transfers","barcodes","product_settings","products","document_cancellations","deliveries","purchase_lines","documents","supplier_receipts","audit"))db.execSQL("DROP TABLE "+table);db.setVersion(2);}try(Store upgraded=new Store(getTargetContext(),file)){eq(upgraded.database().getVersion(),5);eq(upgraded.snapshot().events().size(),2);eq(upgraded.snapshot().receipts().get(0),photo);eq(upgraded.checkout(),pending);eq(new BusinessStore(upgraded).audit().size(),3);}}));
        test("flavourTransferSaleUndoAndDuplicate",()->fresh((s,file)->{var catalog=new CatalogStore(s);String id=Ledger.id();catalog.save(new Catalog.Product(id,"Ultra White",5,24,24,5000,"Supplier"));long now=System.currentTimeMillis();var transfer=new Catalog.Transfer(Ledger.id(),Catalog.LEGACY,id,10,now,"Counted opening stock");catalog.transfer(transfer);catalog.transfer(transfer);eq(catalog.view().stock().get(id),10L);eq(s.snapshot().totals().stock(),20L);var e=sale();catalog.stage(e,id,false);s.recoverPending();s.acknowledge(e.id());catalog.stage(e,id,false);eq(catalog.view().stock().get(id),8L);s.record(Ledger.event("undo",0,"none",0,0,0,"Mistake",now,e.id()));eq(catalog.view().stock().get(id),10L);}));
        test("perFlavourOversaleRejectedAtomically",()->fresh((s,file)->{var catalog=new CatalogStore(s);String id=Ledger.id();catalog.save(new Catalog.Product(id,"Empty flavour",2,12,12,2600,""));try{catalog.stage(sale(),id,false);throw new AssertionError("Sold empty flavour");}catch(IllegalArgumentException expected){}eq(s.snapshot().events().size(),2);eq(s.recoverPending(),null);eq(catalog.view().shopping().get(1).required(),12L);}));
        test("catalogBarcodeBackupAndRestart",()->fresh((s,file)->{var catalog=new CatalogStore(s);String id=Ledger.id();catalog.save(new Catalog.Product(id,"Ultra",5,24,24,5000,"Supplier"));catalog.assign("0012345678905",id,false);catalog.transfer(new Catalog.Transfer(Ledger.id(),Catalog.LEGACY,id,6,System.currentTimeMillis(),"Count"));var incoming=Backup.decode(Backup.encode(s.fullBackup()));String other="catalog-restore-"+UUID.randomUUID()+".db";try(Store replacement=new Store(getTargetContext(),other)){replacement.importBackup(incoming);replacement.importBackup(incoming);eq(new CatalogStore(replacement).lookup("0012345678905").id(),id);eq(new CatalogStore(replacement).view().stock().get(id),6L);replacement.close();try(Store again=new Store(getTargetContext(),other)){eq(new CatalogStore(again).view().stock().get(id),6L);}}finally{getTargetContext().deleteDatabase(other);}}));
        test("bundledBarcodeFirstUseWithoutNetwork",()->{String expected="012345678905";var matrix=new com.google.zxing.MultiFormatWriter().encode(expected,com.google.zxing.BarcodeFormat.UPC_A,1000,360);android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(matrix.getWidth(),matrix.getHeight(),android.graphics.Bitmap.Config.ARGB_8888);for(int y=0;y<matrix.getHeight();y++)for(int x=0;x<matrix.getWidth();x++)image.setPixel(x,y,matrix.get(x,y)?android.graphics.Color.BLACK:android.graphics.Color.WHITE);var scanner=com.google.mlkit.vision.barcode.BarcodeScanning.getClient();try{var codes=com.google.android.gms.tasks.Tasks.await(scanner.process(com.google.mlkit.vision.common.InputImage.fromBitmap(image,0)),45,java.util.concurrent.TimeUnit.SECONDS);check(codes.stream().anyMatch(code->expected.equals(code.getRawValue())||("0"+expected).equals(code.getRawValue())));}finally{scanner.close();image.recycle();}});
        test("bundledReceiptOcrFirstUseWithoutNetwork",()->{android.graphics.Bitmap image=android.graphics.Bitmap.createBitmap(1400,700,android.graphics.Bitmap.Config.ARGB_8888);android.graphics.Canvas canvas=new android.graphics.Canvas(image);canvas.drawColor(android.graphics.Color.WHITE);android.graphics.Paint paint=new android.graphics.Paint();paint.setColor(android.graphics.Color.BLACK);paint.setTextSize(72);paint.setTypeface(android.graphics.Typeface.MONOSPACE);canvas.drawText("MONSTER SUPPLIER",50,150,paint);canvas.drawText("TOTAL $50.00",50,280,paint);canvas.drawText("GST $4.55",50,410,paint);java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();image.compress(android.graphics.Bitmap.CompressFormat.PNG,100,bytes);image.recycle();String text=ReceiptOcr.scan(getTargetContext(),Purchases.receipt(bytes.toByteArray()));check(text.toUpperCase(java.util.Locale.ROOT).contains("MONSTER"));eq(ReceiptParser.parse(text).total(),5000L);});
        test("receiptCameraScreenHandlesUnavailableHardwareOffline",()->{android.app.Activity activity=startActivitySync(new android.content.Intent(getTargetContext(),CameraActivity.class).putExtra("mode","receipt").addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(500);check(!activity.isFinishing());runOnMainSync(activity::finish);});
        test("GSTSettingsOnlyAffectFutureSalesAndPersist",()->fresh((s,file)->{var old=sale();s.record(old);var finance=new FinanceStore(s);finance.saveSettings(true,true,Map.of(Catalog.LEGACY,"taxable"));var future=sale();s.stage(future);finance.saveSettings(false,true,Map.of(Catalog.LEGACY,"taxable"));s.recoverPending();s.acknowledge(future.id());var all=Finance.summarize(finance.result(),Finance.period("all",java.time.LocalDate.now()));eq(all.outputGst(),55L);s.close();try(Store reopened=new Store(getTargetContext(),file)){eq(Finance.summarize(new FinanceStore(reopened).result(),Finance.period("all",java.time.LocalDate.now())).outputGst(),55L);}}));
        test("actualPurchaseGstCreditsPartialGoodsOnly",()->fresh((s,file)->{var b=new BusinessStore(s);var line=new Purchases.Line(Ledger.id(),"Monster",2,1,22,2,true,Catalog.LEGACY);var doc=new Purchases.Document(Ledger.id(),"purchase","Supplier","",null,System.currentTimeMillis(),22,2,"","",null,Ledger.list(line));b.add(doc,null);b.receive(Ledger.id(),line.id(),1,System.currentTimeMillis(),"");new FinanceStore(s).saveSettings(true,true,Map.of(Catalog.LEGACY,"taxable"));b.receive(Ledger.id(),line.id(),1,System.currentTimeMillis(),"");eq(Finance.summarize(new FinanceStore(s).result(),Finance.period("all",java.time.LocalDate.now())).inputGst(),1L);}));
        test("financialSnapshotsBackupAndFlavourCostsRestore",()->fresh((s,file)->{var finance=new FinanceStore(s);finance.saveSettings(true,true,Map.of(Catalog.LEGACY,"taxable"));s.record(sale());String product=Ledger.id();new CatalogStore(s).save(new Catalog.Product(product,"Costed flavour",2,12,12,2500,""));new CatalogStore(s).transfer(new Catalog.Transfer(Ledger.id(),Catalog.LEGACY,product,5,System.currentTimeMillis(),"Count"));var e=sale();new CatalogStore(s).stage(e,product,false);s.recoverPending();s.acknowledge(e.id());var expected=Finance.summarize(finance.result(),Finance.period("all",java.time.LocalDate.now()));var data=Backup.decode(Backup.encode(s.fullBackup()));String other="finance-restore-"+UUID.randomUUID()+".db";try(Store restored=new Store(getTargetContext(),other)){restored.importBackup(data);restored.importBackup(data);var actual=Finance.summarize(new FinanceStore(restored).result(),Finance.period("all",java.time.LocalDate.now()));eq(actual.outputGst(),expected.outputGst());eq(actual.cogs(),expected.cogs());eq(actual.flavourProfit(),expected.flavourProfit());}finally{getTargetContext().deleteDatabase(other);}}));
        test("versionFourUpgradePreservesStockAndDefaultsNoGST",()->fresh((s,file)->{s.record(sale());s.close();try(var db=android.database.sqlite.SQLiteDatabase.openDatabase(getTargetContext().getDatabasePath(file).getPath(),null,0)){for(String table:Ledger.list("finance_tax_plans","finance_tax","finance_settings"))db.execSQL("DROP TABLE "+table);db.setVersion(4);}try(Store upgraded=new Store(getTargetContext(),file)){eq(upgraded.database().getVersion(),5);eq(upgraded.snapshot().totals().stock(),18L);eq(Finance.summarize(new FinanceStore(upgraded).result(),Finance.period("all",java.time.LocalDate.now())).outputGst(),0L);}}));
        test("reportsExportValidPDFWithoutInternet",()->{java.io.ByteArrayOutputStream bytes=new java.io.ByteArrayOutputStream();ReportsActivity.writePdf(bytes,"Monster offline financial report\nRevenue AUD $0.00\nUnknown opening dates preserved.");byte[] pdf=bytes.toByteArray();check(pdf.length>100);eq(new String(java.util.Arrays.copyOf(pdf,4),java.nio.charset.StandardCharsets.US_ASCII),"%PDF");android.app.Activity activity=startActivitySync(new android.content.Intent(getTargetContext(),ReportsActivity.class).addFlags(android.content.Intent.FLAG_ACTIVITY_NEW_TASK));Thread.sleep(1000);check(!activity.isFinishing());runOnMainSync(activity::finish);});
        Bundle done=new Bundle();done.putString("stream","\nDEVICE RESULTS: "+passed+" passed, "+failed+" failed.\n");finish(failed==0?Activity.RESULT_OK:Activity.RESULT_CANCELED,done);
    }
}
